66	// ListClusters returns list of clusters
67	func (db *db) ListClusters(_ context.Context) (*appv1.ClusterList, error) {
68		clusterSecrets, err := db.listSecretsByType(common.LabelValueSecretTypeCluster)
69		if err != nil {
70			return nil, err
71		}
72		clusterList := appv1.ClusterList{
73			Items: make([]appv1.Cluster, 0),
74		}
75		inClusterEnabled, err := db.settingsMgr.IsInClusterEnabled()
76		if err != nil {
77			log.Warnf(errCheckingInClusterEnabled, "ListClusters", err)
78		}
79		hasInClusterCredentials := false
80		for _, clusterSecret := range clusterSecrets {
81			cluster, err := SecretToCluster(clusterSecret)
82			if err != nil {
83				log.Errorf("could not unmarshal cluster secret %s", clusterSecret.Name)
84				continue
85			}
86			if cluster.Server == appv1.KubernetesInternalAPIServerAddr {
87				if inClusterEnabled {
88					hasInClusterCredentials = true
89					clusterList.Items = append(clusterList.Items, *cluster)
90				}
91			} else {
92				clusterList.Items = append(clusterList.Items, *cluster)
93			}
94		}
95		if inClusterEnabled && !hasInClusterCredentials {
96			clusterList.Items = append(clusterList.Items, *db.getLocalCluster())
97		}
98		return &clusterList, nil
99	}
